import{af as a,z as t,J as r,ab as i}from"./chunks/framework.C1QHhBQn.js";const f=JSON.parse('{"title":"Powered Vehicle RTK (VTRTK)","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"devices/rtk/vehicle.md","filePath":"devices/rtk/vehicle.md"}'),d={name:"devices/rtk/vehicle.md"};function o(s,e,c,n,h,l){return t(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...e[0]||(e[0]=[i('<h1 id="powered-vehicle-rtk-vtrtk" tabindex="-1">Powered Vehicle RTK (VTRTK) <a class="header-anchor" href="#powered-vehicle-rtk-vtrtk" aria-label="Permalink to &quot;Powered Vehicle RTK (VTRTK)&quot;">​</a></h1><p>A powered RTK tracker for vehicles, with advanced GNSS and RTK capabilities.</p><p>Currently available for demo, with the form factor of a <a href="/docs/pr/40/devices/vehicle/">VT3</a> device and high-accuracy RTK positioning. It is a separate hardware model from the <a href="/docs/pr/40/devices/rtk/handheld/">RH2 handheld</a>; do not assume identical LEDs, wireless features or application support.</p><h2 id="led-indicators" tabindex="-1">LED indicators <a class="header-anchor" href="#led-indicators" aria-label="Permalink to &quot;LED indicators&quot;">​</a></h2><p>VTRTK uses four indicators for the standard battery and ignition/charging display, not RH2’s RGB status colours. See the <a href="/docs/pr/40/guides/rtk-leds#vehicle-rtk-vtrtk">VTRTK LED guide</a> for the matching patterns and revision caveats.</p>',5)])])}const v=a(d,[["render",o]]);export{f as __pageData,v as default};
